const loadedFonts=new Set();
function fontKind(bytes){const h=String.fromCharCode(bytes[0],bytes[1],bytes[2],bytes[3]);if(h==='OTTO')return 'otf';if(h==='true'||h==='typ1'||(bytes[0]===0&&bytes[1]===1&&bytes[2]===0&&bytes[3]===0))return 'ttf';return '';}
function bytesToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary);}
async function ensureFonts(){let added=false;for(const font of doc.fonts||[]){if(loadedFonts.has(font.id))continue;try{const face=new FontFace(font.id,`url(${font.dataUrl})`);await face.load();document.fonts.add(face);loadedFonts.add(font.id);added=true;}catch(e){loadedFonts.add(font.id);notify('Шрифт «'+font.name+'» не подключился',true);}}return added;}
function strokeActive(l){return l.strokeOn!=null?!!l.strokeOn:(l.strokeWidth||0)>0;}
function colorOpacity(key){const l=selectedLayer();if(key==='stroke')return l?.strokeOpacity??100;if(key==='shadow.color')return l?.shadow?.opacity??35;return l?.opacity??100;}
function fontChoices(){return [['Arial','Arial'],['Georgia','Georgia'],['Times New Roman','Times New Roman'],...(doc.fonts||[]).map(f=>[f.id,f.name])];}
function fontRow(layer,prefix=''){const key=prefix+'font',options=fontChoices().map(([k,n])=>`<option value="${esc(k)}" ${layer.font===k?'selected':''} style="font-family:'${esc(k)}',sans-serif">${esc(n)}</option>`).join('');const mine=(doc.fonts||[]).find(f=>f.id===layer.font);return `<div class="font-row"><label class="font-select"><select data-prop="${key}" aria-label="Шрифт">${options}</select><i class="type-chevron" aria-hidden="true"></i></label><label class="font-add" title="Добавить шрифт" aria-label="Добавить шрифт"><input id="font-upload" data-font-target="${key}" type="file" accept=".ttf,.otf,font/ttf,font/otf"><span aria-hidden="true">＋</span></label></div>${mine?`<button type="button" class="text-button" data-font-remove="${esc(mine.id)}">Убрать «${esc(mine.name)}»</button>`:''}`;}
function markIcon(name){const paths={left:'M4 6h16M4 12h10M4 18h16',center:'M4 6h16M7 12h10M4 18h16',right:'M4 6h16M10 12h10M4 18h16',justify:'M4 6h16M4 12h16M4 18h16',solid:'M4 12h16',dashed:'M4 12h3.5M10.2 12h3.5M16.5 12h3.5',dotted:'M5 12h.1M9 12h.1M13 12h.1M17 12h.1M21 12h.1',centerStroke:'M6 6h12v12H6z',outside:'M4 4h16v16H4zM7 7h10v10H7z'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"/></svg>`;}
function styleButton(on,attrs,label,glyph){return `<button type="button" class="icon-toggle" ${attrs} aria-pressed="${on?'true':'false'}" aria-label="${label}" title="${label}">${glyph}</button>`;}
function textStyleBar(l,prefix=''){const flags=[['bold','Жирный','<b>B</b>'],['italic','Курсив','<i>I</i>'],['underline','Подчёркнутый','<span class="u">U</span>'],['strike','Зачёркнутый','<span class="s">S</span>']];return `<div class="segments" role="toolbar" aria-label="Начертание">${flags.map(([key,name,icon])=>`<button type="button" data-choice="${prefix+key}" data-value="toggle" class="${l[key]?'active':''}" title="${name}" aria-label="${name}" aria-pressed="${l[key]?'true':'false'}">${icon}</button>`).join('')}</div>`;}
