function scrubField(label,key,value,min,max,step,icon,suffix=''){const v=Number(value),fullLabel=key==='letterSpacing'?'Межбуквенный интервал':label,attrs=`data-scrub="${key}" data-min="${min}" data-max="${max}" data-step="${step}" title="${fullLabel}: потяните влево или вправо"`;return `<div class="type-field ${key==='fontSize'?'type-font-size':''}">${key==='fontSize'?'':`<span class="type-label">${label}</span>`}<div class="type-value${suffix?' type-value-suffixed':''}" ${attrs}><span class="type-inline-scrub" aria-hidden="true">${icon}</span><input data-live="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${v}" ${suffix?`style="width:${Math.max(1,String(v).length)}ch"`:''} aria-label="${fullLabel}">${suffix?`<span class="type-suffix">${suffix}</span>`:''}</div></div>`;}

