/* Auto text: static text with data chips. The layer keeps one string with {{field}} tokens. */
let chipRange=null,autoTextTimer=0;
function chipHtml(field){return `<span class="text-chip" contenteditable="false" data-field="${esc(field)}">${esc(AutoText.FIELDS[field])}</span>`;}
function autoTextField(l){const groups=AutoText.GROUPS.map(([title,rows])=>`<p class="menu-label">${esc(title)}</p>${rows.map(([field,label])=>`<button type="button" class="chip-row" role="menuitem" data-insert-chip="${esc(field)}"><span class="text-chip">${esc(label)}</span></button>`).join('')}`).join('');return `<div class="auto-text-field"><div class="auto-text" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Текст" spellcheck="false" data-auto-text>${AutoText.parts(l.text).map(part=>part.field?chipHtml(part.field):esc(part.text)).join('')}</div><button type="button" class="auto-text-add" data-chip-menu aria-haspopup="menu" aria-expanded="false" title="Вставить данные заказа">＋ Данные</button><div class="chip-menu" role="menu" aria-label="Данные заказа" hidden>${groups}</div></div><p class="section-note">Чипы заменяются данными каждого альбома; пустое значение не печатается.</p>`;}
function autoTextValue(box){let out='';const walk=node=>{for(const n of node.childNodes){if(n.nodeType===3)out+=n.nodeValue;else if(n.dataset?.field)out+=AutoText.token(n.dataset.field);else if(n.nodeName==='BR')out+='\n';else{if(/^(DIV|P)$/.test(n.nodeName)&&out&&!out.endsWith('\n'))out+='\n';walk(n);}}};walk(box);return out.replace(/\u200b/g,'').slice(0,2000);}
function autoTextInput(box){const layer=selectedLayer();if(!layer||layer.type!=='text')return;if(!slide)slide={start:clone(doc)};layer.text=autoTextValue(box);clearTimeout(autoTextTimer);autoTextTimer=setTimeout(renderScene,200);}
function insertChip(field){const box=$('#inspector [data-auto-text]');if(!box||!(field in AutoText.FIELDS))return;const range=chipRange&&box.contains(chipRange.startContainer)?chipRange:(()=>{const r=document.createRange();r.selectNodeContents(box);r.collapse(false);return r;})();const holder=document.createElement('span');holder.innerHTML=chipHtml(field);const chip=holder.firstChild;range.deleteContents();range.insertNode(chip);const after=document.createRange();after.setStartAfter(chip);after.collapse(true);const sel=getSelection();sel.removeAllRanges();sel.addRange(after);chipRange=after.cloneRange();autoTextInput(box);box.focus();}
function bindAutoText(){const host=$('#inspector');document.addEventListener('selectionchange',()=>{const sel=getSelection();if(!sel.rangeCount)return;const node=sel.anchorNode,el=node?.nodeType===1?node:node?.parentElement;if(el?.closest('[data-auto-text]'))chipRange=sel.getRangeAt(0).cloneRange();});const closeChips=()=>host.querySelectorAll('.chip-menu:not([hidden])').forEach(menu=>{menu.hidden=true;menu.parentElement.querySelector('[data-chip-menu]')?.setAttribute('aria-expanded','false');});document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('.auto-text-field'))closeChips();},true);host.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest?.('.auto-text-field')){closeChips();return;}if(e.target.closest?.('[data-auto-text]')&&e.key==='Enter'){e.preventDefault();document.execCommand('insertText',false,'\n');}});host.addEventListener('paste',e=>{if(!e.target.closest?.('[data-auto-text]'))return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));});host.addEventListener('input',e=>{const box=e.target.closest?.('[data-auto-text]');if(box)autoTextInput(box);});host.addEventListener('focusout',e=>{if(!e.target.closest?.('[data-auto-text]')||e.relatedTarget?.closest?.('.auto-text-field'))return;clearTimeout(autoTextTimer);if(slide)finishSlide();});host.addEventListener('pointerdown',e=>{if(e.target.closest('[data-insert-chip],[data-chip-menu]'))e.preventDefault();});host.addEventListener('click',e=>{const toggle=e.target.closest('[data-chip-menu]');if(toggle){e.stopPropagation();const menu=toggle.parentElement.querySelector('.chip-menu'),open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));return;}const item=e.target.closest('[data-insert-chip]');if(item){e.stopPropagation();item.closest('.chip-menu').hidden=true;insertChip(item.dataset.insertChip);}},true);}
function textPanel(l){const style=textStyle(l),styleName=style?.name||'Без общего стиля';return `<div class="type-style-row"><div class="type-style-select"><span class="type-label">Общий стиль</span><button type="button" class="type-style-trigger" data-open-style-menu aria-haspopup="dialog" aria-expanded="false" aria-label="Выбрать общий стиль: ${esc(styleName)}"><span>${esc(styleName)}</span><i class="type-chevron" aria-hidden="true"></i></button></div><div class="text-style-actions"><button type="button" data-text-style="create" title="Создать стиль" aria-label="Создать стиль">＋</button>${style?`<button type="button" data-text-style="rename" title="Переименовать стиль" aria-label="Переименовать стиль">✎</button>`:''}</div></div>${style?'<p class="section-note">Изменения применяются ко всем текстам этого стиля.</p>':''}<div class="type-font">${fontRow(l)}</div><div class="type-main-row"><div class="type-weight"><select data-prop="bold" aria-label="Начертание"><option value="false" ${!l.bold?'selected':''}>Обычное</option><option value="true" ${l.bold?'selected':''}>Жирное</option></select><i class="type-chevron" aria-hidden="true"></i></div>${scrubField('Размер текста','fontSize',l.fontSize,4,120,1,'<span class="type-size-icon">A</span>')}</div><div class="type-metrics">${scrubField('Интерлиньяж','lineHeight',l.lineHeight??1.25,0.8,3,0.05,'<svg class="type-line-height-icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 3h10M8 17h10M4 5v10M2 7l2-2 2 2M2 13l2 2 2-2"/></svg>')}${scrubField('Интервал','letterSpacing',l.letterSpacing??0,-20,80,1,'<span class="type-metric-icon">A↔</span>','%')}${scrubField('Наклон','skew',l.skew??0,-30,30,1,'<span class="type-metric-icon type-skew-icon">A</span>','°')}</div><div class="type-align"><span class="type-label">Выравнивание</span>${textAlignBar(l.align)}</div><div class="type-extras">${textStyleBar(l)}</div>${colorControl('Цвет','color',l.color||'#333333')}`;}
function gridTextPanel(l,prefix=''){const prefixed=key=>prefix?prefix+key[0].toUpperCase()+key.slice(1):key,value=(key,fallback)=>l[prefixed(key)]??fallback,settings={font:value('font',l.font||'Georgia'),fontSize:value('fontSize',prefix?9:l.fontSize),bold:value('bold',prefix?false:!!l.bold),italic:value('italic',prefix?false:!!l.italic),underline:value('underline',prefix?false:!!l.underline),strike:value('strike',prefix?false:!!l.strike),lineHeight:value('lineHeight',1.25),letterSpacing:value('letterSpacing',0),align:value('align','center'),color:value('color',l.color||'#333333')};let html=textPanel(settings),start=html.indexOf('<div class="type-font">');html=html.slice(start);if(prefix)html=html.replace(/(data-(?:prop|live|choice|color-key|scrub|font-target)=")([^"]+)/g,(_,attr,key)=>attr+prefixed(key));return html;}
let vignetteTextTab='name',vignetteDialogTab='layout';
const vignetteGapIcon={gap:'<rect x="2" y="4" width="4.5" height="12" rx="1"/><rect x="13.5" y="4" width="4.5" height="12" rx="1"/><path d="M8.5 10h3M9.5 8.5 8.3 10l1.2 1.5M10.5 8.5l1.2 1.5-1.2 1.5"/>',photoNameGap:'<rect x="4" y="2" width="12" height="7.5" rx="1"/><path d="M10 11.5v3.5M8.6 12.8 10 11.5l1.4 1.3M8.6 13.7 10 15l1.4-1.3M5 18h10"/>',nameDetailGap:'<path d="M4 3.5h12M10 6.5v6M8.6 7.8 10 6.5l1.4 1.3M8.6 11.2 10 12.5l1.4-1.3M6 16h8M7.5 18.5h5"/>'};
