function vignettePanel(l){const teachers=l.source==='teachers',row=(name,value)=>`<div>${name}<strong>${value}</strong></div>`;return `<section class="inspector-section"><div class="inspector-heading safety-heading"><h3>${teachers?'Виньетки учителей':'Виньетки учеников'}</h3><button type="button" class="safety-edit" data-open-vignette>Настроить</button></div><div class="safety-summary">${row('Карточек на странице',`${blockList(section()).min}–${blockList(section()).max}`)}${row('Ширина фото',`${round(l.minPhotoWidth)}–${round(l.photoWidth??85)} мм`)}${row('Подпись',l.showDetail?(teachers?'Имя и предмет':'Имя и цитата'):'Только имя')}</div></section>`+`<section class="inspector-section typography-section"><div class="typography-heading"><h3>Отступы</h3></div><div class="type-metrics vignette-gaps">${vignetteGapField(l,'gap')}${vignetteGapField(l,'photoNameGap')}${l.showDetail?vignetteGapField(l,'nameDetailGap'):''}</div></section>`;}
