function vignetteSettings(l){
 if(vignetteDialogTab==='layout'){const pair=(title,low,high,unit,attrs)=>`<div class="vignette-pair"><span>${title}</span><label>от<input data-prop="${low}" type="number" value="${round(l[low])}" ${attrs} aria-label="${title}: от"></label><label>до<input data-prop="${high}" type="number" value="${round(l[high]??85)}" ${attrs} aria-label="${title}: до"></label><em>${unit}</em></div>`,list=blockList(section());return `<div class="vignette-dialog-group"><div class="vignette-block-note"><span><strong>${list.source==='teachers'?'Учителя':'Ученики'} · ${list.min}–${list.max} на странице</strong><small>Кого и сколько карточек разместить — в настройках блока слева.</small></span><button type="button" data-vignette-block>Изменить</button></div>${pair('Ширина фото','minPhotoWidth','photoWidth','мм','min="5" max="180"')}<p class="vignette-field-note">Если карточки не помещаются, фото уменьшается до нижней границы, а дальше карточки переходят на следующую страницу. Отступы меняются на самой странице и в правой панели.</p></div>`;}
 const name=vignetteDetailName(l),show=!!l.showDetail,tab=show&&vignetteTextTab==='detail'?'detail':'name';return `<div class="vignette-dialog-group"><div class="vignette-detail-row"><span><strong>Показывать ${name==='Цитата'?'цитаты':'предметы'}</strong><small>Под именем на каждой виньетке</small></span><button type="button" class="switch${show?' on':''}" data-choice="showDetail" aria-pressed="${show}" aria-label="${show?'Скрыть':'Показать'} ${name.toLowerCase()}"></button></div>${show?`<div class="segments vignette-text-tabs" role="tablist" aria-label="Настройки подписей"><button type="button" data-vignette-type="name" role="tab" class="${tab==='name'?'active':''}" aria-selected="${tab==='name'}">Имя</button><button type="button" data-vignette-type="detail" role="tab" class="${tab==='detail'?'active':''}" aria-selected="${tab==='detail'}">${name}</button></div>`:''}<div class="typography-section">${tab==='detail'?gridTextPanel(l,'detail'):gridTextPanel(l)+`<div class="type-metrics vignette-min-size">${scrubField('Уменьшать до','minFontSize',l.minFontSize,4,120,0.5,'<span class="type-metric-icon">A↓</span>','pt')}<p>Если длинное имя не помещается в две строки, кегль всех имён блока уменьшается до этого размера.</p></div>`}</div></div>`;
}
let vignettePage=0,vignettePreviewFrame=0,vignettePreviewToken=0,vignetteCanvas=null;
function vignettePreview(){if(vignettePreviewFrame)return;vignettePreviewFrame=requestAnimationFrame(()=>{vignettePreviewFrame=0;drawVignettePreview();});}
/* The preview is the real page render at a smaller zoom, so type, effects and spacing always match the canvas. */
async function drawVignettePreview(){const l=selectedLayer(),dialog=$('#vignette-dialog'),stage=dialog.querySelector('.vignette-preview-stage');if(!l||l.type!=='grid'||!dialog.open||!stage||!window.fabric)return;const token=++vignettePreviewToken,plan=plans.find(p=>p.sectionId===section().id),pages=(plan?.pages||[]).filter(g=>g.records),issues=plan?.issues||[];vignettePage=clamp(vignettePage,0,Math.max(0,pages.length-1));const g=pages[vignettePage],template=g?planner.getTemplatePage(g.templateId):null,layer=template?.layers.find(item=>item.type==='grid'&&!item.hidden)||l,noun=l.source==='teachers'?'учителей':'учеников';
$('#vignette-preview-head').innerHTML=`<strong>Пример</strong>${pages.length>1?`<div class="vignette-pages"><button type="button" data-vignette-page="-1" aria-label="Предыдущая страница"${vignettePage?'':' disabled'}>‹</button><span>Страница ${vignettePage+1} из ${pages.length}</span><button type="button" data-vignette-page="1" aria-label="Следующая страница"${vignettePage<pages.length-1?'':' disabled'}>›</button></div>`:''}`;
$('#vignette-preview-issues').innerHTML=issues.map(i=>`<div class="issue ${i.severity}">${esc(i.text)}</div>`).join('');
const built=g&&g.records.length?await vignetteChildren(layer,g,template?.background):null;if(token!==vignettePreviewToken)return;const empty=$('#vignette-preview-empty'),facts=$('#vignette-preview-facts');
if(!built?.geo){empty.hidden=false;empty.textContent=g&&g.records.length||!plan?'Карточки не помещаются. Уменьшите нижнюю границу ширины фото или отступы.':`В примере нет ${noun}. Укажите количество выше.`;facts.innerHTML='';vignetteCanvas?.clear();return;}empty.hidden=true;
const pw=pageWidth(),ph=pageHeight(),width=Math.max(160,stage.clientWidth-2),scale=Math.min(width/pw,440/ph);if(!vignetteCanvas)vignetteCanvas=new fabric.StaticCanvas('vignette-preview-canvas',{renderOnAddRemove:false});const size={width:Math.round(pw*scale),height:Math.round(ph*scale)};if(vignetteCanvas.width!==size.width||vignetteCanvas.height!==size.height)vignetteCanvas.setDimensions(size);vignetteCanvas.setZoom(scale);vignetteCanvas.clear();vignetteCanvas.backgroundColor=template?.background||'#fff';const b=layer.box;vignetteCanvas.add(boxGroup(built.children,{left:b.x+b.w/2,top:b.y+b.h/2,originX:'center',originY:'center',width:b.w,height:b.h,angle:layer.angle||0,opacity:(layer.opacity??100)/100,objectCaching:false}),new fabric.Rect({left:b.x,top:b.y,width:b.w,height:b.h,fill:'transparent',stroke:'#b9a6c8',strokeWidth:1/scale,strokeDashArray:[4/scale,3/scale],angle:layer.angle||0}));vignetteCanvas.renderAll();
const count=g.records.length;facts.innerHTML=`<span>${count} ${count%10===1&&count%100!==11?'карточка':[2,3,4].includes(count%10)&&![12,13,14].includes(count%100)?'карточки':'карточек'}</span><span>Фото <b>${mmLabel(built.geo.photoW)}</b></span><span>Имя <b>${round(g.actualFont||layer.fontSize)} pt</b></span>`;}
function renderVignetteDialog(){const l=selectedLayer();if(!l||l.type!=='grid')return;$('#vignette-dialog-title').textContent=l.source==='teachers'?'Виньетки учителей':'Виньетки учеников';$$('#vignette-dialog [data-vignette-dialog-tab]').forEach(b=>{const active=b.dataset.vignetteDialogTab===vignetteDialogTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$('#vignette-controls').innerHTML=vignetteSettings(l);const source=l.source,noun=source==='teachers'?'учителей':'учеников';$('#vignette-test-count').innerHTML=`<label class="vignette-sample-count">В примере<input data-vignette-test-count="${source}" type="number" min="0" max="${source==='teachers'?60:80}" value="${view[source]}" aria-label="Количество ${noun} в примере">${noun}</label><div class="vignette-test-flags"><label class="check"><input type="checkbox" data-vignette-test-flag="long" ${view.long?'checked':''}>Длинное имя</label><label class="check"><input type="checkbox" data-vignette-test-flag="missing" ${view.missing?'checked':''}>Нет портрета</label></div>`;vignettePreview();}
