vignetteDialog.addEventListener('input',e=>{const el=e.target;if(el.dataset.vignetteTestCount){if(el.value!==''&&el.validity.valid){view[el.dataset.vignetteTestCount]=Number(el.value);planner=MasterPlanner(doc,view);plans=planner.plan();vignettePreview();renderScene();}return;}const key=el.dataset.live||(el.type==='number'?el.dataset.prop:null);if(!key||el.value===''||!el.validity.valid)return;vignetteLive(key,Number(el.value),el);});
vignetteDialog.addEventListener('change',e=>{const el=e.target;if(el.dataset.vignetteTestCount)return;if(el.dataset.vignetteTestFlag){view[el.dataset.vignetteTestFlag]=el.checked;planner=MasterPlanner(doc,view);plans=planner.plan();vignettePreview();renderScene();return;}if(el.id==='font-upload'){uploadVignetteFont(el);return;}if(el.dataset.live||el.type==='number'&&el.dataset.prop){finishSlide();vignettePreview();return;}const key=el.dataset.prop;if(!key)return;const value=['bold','detailBold'].includes(key)?el.value==='true':el.type==='checkbox'?el.checked:el.value;property(key,value);renderVignetteDialog();});
