/* Block rules live in the block's card on the left: how it unfolds, whom it is for and the roles of its spreads. */
const ROLE_NAMES={intro:'Открывающий',repeat:'Повторяемый',last:'Последний неполный',outro:'Закрывающий'};
const ROLE_HELP={intro:'один раз в начале блока',repeat:'повторяется, пока в списке есть люди',last:'заменяет повторяемый разворот, если список закончился на его середине',outro:'один раз в конце блока'};
