  if(s.kind==='flow')body+=`<details class="block-roles-help"><summary>Что значат роли</summary>${MasterPlan.ROLES.map(r=>`<p><b>${ROLE_NAMES[r]}</b> — ${ROLE_HELP[r]}.</p>`).join('')}</details>`;
